import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { projectsAPI, contractsAPI } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import { usePermissions } from '../../context/PermissionsContext';
import AppLayout from '../../components/layout/AppLayout';
import RoleBadge from '../../components/ui/RoleBadge';

// ── Shared helpers ────────────────────────────────────────────────────────

const fmtFCFA = (n) => {
  if (!n) return '0 FCFA';
  if (n >= 1_000_000_000) return `${(n/1_000_000_000).toFixed(1)}Mrd FCFA`;
  if (n >= 1_000_000)     return `${(n/1_000_000).toFixed(0)}M FCFA`;
  return `${Number(n).toLocaleString('fr-FR')} FCFA`;
};

const STATUS_CFG = {
  planifie: { label:'Planifié',  color:'#6366F1', bg:'rgba(99,102,241,0.12)'  },
  en_cours: { label:'En cours',  color:'#F59E0B', bg:'rgba(245,158,11,0.12)'  },
  suspendu: { label:'Suspendu',  color:'#EF4444', bg:'rgba(239,68,68,0.12)'   },
  termine:  { label:'Terminé',   color:'#10B981', bg:'rgba(16,185,129,0.12)'  },
};

function KPI({ label, value, sub, color='#F59E0B', alert, trend }) {
  return (
    <div style={{ background:'#111827', border:`1px solid ${alert?'rgba(239,68,68,0.4)':'rgba(255,255,255,0.07)'}`, borderRadius:12, padding:'20px 22px', position:'relative' }}>
      {alert && <span style={{ position:'absolute', top:10, right:10, width:7, height:7, borderRadius:'50%', background:'#EF4444' }} />}
      <div style={{ fontSize:26, fontWeight:800, color: alert?'#EF4444':color, fontFamily:'Bebas Neue', letterSpacing:1, marginBottom:4 }}>{value}</div>
      <div style={{ fontSize:11, color:'#6B7280', textTransform:'uppercase', letterSpacing:'0.6px' }}>{label}</div>
      {sub && <div style={{ fontSize:11, color: alert?'#EF4444':'#9CA3AF', marginTop:4 }}>{sub}</div>}
      {trend && <div style={{ fontSize:11, color:'#10B981', marginTop:4 }}>↑ {trend}</div>}
    </div>
  );
}

function Alert({ text, type='warning' }) {
  const colors = { warning:'rgba(245,158,11,0.12)', danger:'rgba(239,68,68,0.1)', info:'rgba(59,130,246,0.1)' };
  const borders = { warning:'rgba(245,158,11,0.3)', danger:'rgba(239,68,68,0.3)', info:'rgba(59,130,246,0.2)' };
  const textClr = { warning:'#F59E0B', danger:'#FCA5A5', info:'#93C5FD' };
  return (
    <div style={{ background:colors[type], border:`1px solid ${borders[type]}`, borderRadius:10, padding:'12px 16px', marginBottom:20, fontSize:13, color:textClr[type], display:'flex', alignItems:'center', gap:10 }}>
      <span style={{ fontSize:16 }}>{type==='warning'?'⚠️':type==='danger'?'🔴':'ℹ️'}</span>
      {text}
    </div>
  );
}

function SectionTitle({ children, action, actionTo }) {
  return (
    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:14 }}>
      <h2 style={{ fontFamily:'Bebas Neue', fontSize:20, color:'#fff', letterSpacing:1, margin:0 }}>{children}</h2>
      {action && <Link to={actionTo} style={{ fontSize:12, color:'#F59E0B', textDecoration:'none', fontFamily:'Barlow Condensed', fontWeight:600 }}>{action} →</Link>}
    </div>
  );
}

function GanttBar({ label, pct, color, delayed }) {
  return (
    <div style={{ marginBottom:12 }}>
      <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, color:'#D1D5DB', marginBottom:5 }}>
        <span>{label}</span>
        <span style={{ color: delayed?'#EF4444':'#9CA3AF' }}>{pct}%</span>
      </div>
      <div style={{ height:8, background:'rgba(255,255,255,0.07)', borderRadius:4, overflow:'hidden' }}>
        <div style={{ height:'100%', width:`${pct}%`, background: pct>85?'#EF4444':pct>60?'#F59E0B':'#3B82F6', borderRadius:4, transition:'width 0.6s ease' }} />
      </div>
    </div>
  );
}

function BudgetBar({ label, prevuM, reelM }) {
  const pct = prevuM > 0 ? Math.min(100, Math.round((reelM/prevuM)*100)) : 0;
  const color = pct > 90 ? '#EF4444' : pct > 75 ? '#F59E0B' : '#10B981';
  return (
    <div style={{ marginBottom:16 }}>
      <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, marginBottom:4 }}>
        <span style={{ color:'#D1D5DB', fontWeight:600 }}>{label}</span>
        <span style={{ color:'#6B7280', fontSize:12 }}>Prévu {prevuM}M → Réel {reelM}M &nbsp;<span style={{ color }}>{pct}%</span></span>
      </div>
      <div style={{ height:6, background:'rgba(255,255,255,0.07)', borderRadius:3, overflow:'hidden' }}>
        <div style={{ height:'100%', width:`${pct}%`, background:color, borderRadius:3 }} />
      </div>
    </div>
  );
}

function StatusBadge({ status }) {
  const cfg = STATUS_CFG[status] || STATUS_CFG.planifie;
  return <span style={{ padding:'2px 10px', borderRadius:100, fontSize:11, fontWeight:600, color:cfg.color, background:cfg.bg }}>{cfg.label}</span>;
}

function ProjectRow({ p, showBudget }) {
  return (
    <Link to={`/projects/${p.id}`} style={{ textDecoration:'none' }}>
      <div style={{ display:'flex', alignItems:'center', gap:12, padding:'12px 16px', borderRadius:10, background:'rgba(255,255,255,0.03)', border:'1px solid rgba(255,255,255,0.06)', marginBottom:8, cursor:'pointer', transition:'background 0.15s' }}
        onMouseEnter={e=>e.currentTarget.style.background='rgba(255,255,255,0.06)'}
        onMouseLeave={e=>e.currentTarget.style.background='rgba(255,255,255,0.03)'}>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontSize:14, fontWeight:600, color:'#fff', whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{p.name}</div>
          {p.location && <div style={{ fontSize:11, color:'#6B7280' }}>📍 {p.location}</div>}
        </div>
        <StatusBadge status={p.status} />
        {showBudget && p.budget_consumed_pct != null && (
          <span style={{ fontSize:12, color: p.budget_consumed_pct>85?'#EF4444':'#9CA3AF', fontWeight:600, minWidth:36, textAlign:'right' }}>{p.budget_consumed_pct}%</span>
        )}
      </div>
    </Link>
  );
}

// ══════════════════════════════════════════════════════════════════════════
// DASHBOARD VARIANTS
// ══════════════════════════════════════════════════════════════════════════

// 1. SUPER ADMIN — Platform overview (Image 1)
function DashboardSuperAdmin({ projects, contracts, user }) {
  const totalBudget = projects.reduce((a,p)=>a+(parseFloat(p.budget)||0),0);
  const totalExp    = projects.reduce((a,p)=>a+(parseFloat(p.actual_expenses)||0),0);
  const overBudget  = projects.filter(p=>p.budget_consumed_pct>100).length;
  const delayed     = projects.filter(p=>p.end_date&&new Date(p.end_date)<new Date()&&p.status!=='termine').length;

  return (
    <>
      {overBudget>0 && <Alert text={`${overBudget} projet(s) en dépassement budgétaire — action requise`} type="danger" />}
      {delayed>0    && <Alert text={`${delayed} projet(s) en retard sur la livraison prévue`} type="warning" />}

      <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:14, marginBottom:28 }}>
        <KPI label="Projets actifs"    value={projects.filter(p=>p.status==='en_cours').length} color="#F59E0B" trend="+3 ce mois" />
        <KPI label="Chantiers total"   value={projects.length}  color="#6366F1" />
        <KPI label="Utilisateurs"      value="312"              color="#10B981" sub="actifs sur la plateforme" />
        <KPI label="Revenu mensuel"    value="4.2M FCFA"        color="#06B6D4" trend="+12% vs mois passé" />
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:20 }}>
        <div style={{ background:'#111827', border:'1px solid rgba(255,255,255,0.07)', borderRadius:14, padding:22 }}>
          <SectionTitle action="Voir tout" actionTo="/projects">Entreprises abonnées</SectionTitle>
          <table style={{ width:'100%', borderCollapse:'collapse', fontSize:13 }}>
            <thead>
              <tr style={{ color:'#6B7280' }}>
                {['Entreprise','Plan','Chantiers','Statut'].map(h=>(
                  <th key={h} style={{ textAlign:'left', padding:'6px 8px', fontWeight:600, fontSize:11, textTransform:'uppercase', letterSpacing:'0.5px', borderBottom:'1px solid rgba(255,255,255,0.06)' }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {[
                {name:'BTPKO Mali',    plan:'Pro',        n:5,  statut:'Actif',  sc:'#10B981'},
                {name:'Construire SA', plan:'Starter',    n:2,  statut:'Actif',  sc:'#10B981'},
                {name:'Mali Infra',    plan:'Enterprise', n:12, statut:'Actif',  sc:'#10B981'},
                {name:'Bamako Build',  plan:'Pro',        n:4,  statut:'Actif',  sc:'#10B981'},
                {name:'Segou BTP',     plan:'Starter',    n:1,  statut:'Essai',  sc:'#F59E0B'},
              ].map((r,i)=>(
                <tr key={i} style={{ borderBottom:'1px solid rgba(255,255,255,0.04)' }}>
                  <td style={{ padding:'10px 8px', color:'#fff', fontWeight:600 }}>{r.name}</td>
                  <td style={{ padding:'10px 8px' }}>
                    <span style={{ padding:'2px 10px', borderRadius:100, fontSize:11, fontWeight:600,
                      background: r.plan==='Enterprise'?'rgba(99,102,241,0.15)':r.plan==='Pro'?'rgba(16,185,129,0.12)':'rgba(156,163,175,0.12)',
                      color: r.plan==='Enterprise'?'#818CF8':r.plan==='Pro'?'#34D399':'#9CA3AF' }}>
                      {r.plan}
                    </span>
                  </td>
                  <td style={{ padding:'10px 8px', color:'#D1D5DB' }}>{r.n}</td>
                  <td style={{ padding:'10px 8px' }}>
                    <span style={{ padding:'2px 10px', borderRadius:100, fontSize:11, fontWeight:600, color:r.sc, background:`${r.sc}1a` }}>{r.statut}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div style={{ background:'#111827', border:'1px solid rgba(255,255,255,0.07)', borderRadius:14, padding:22 }}>
          <SectionTitle>Modules les plus utilisés</SectionTitle>
          {[
            { label:'Planning / Gantt',   pct:88, color:'#3B82F6' },
            { label:'Finance & Achats',   pct:74, color:'#EF4444' },
            { label:'Journal terrain',    pct:65, color:'#10B981' },
          ].map((m,i)=>(
            <div key={i} style={{ marginBottom:16 }}>
              <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, color:'#D1D5DB', marginBottom:5 }}>
                <span>{m.label}</span><span style={{ color:'#9CA3AF' }}>{m.pct}%</span>
              </div>
              <div style={{ height:7, background:'rgba(255,255,255,0.07)', borderRadius:4, overflow:'hidden' }}>
                <div style={{ height:'100%', width:`${m.pct}%`, background:m.color, borderRadius:4 }} />
              </div>
            </div>
          ))}

          <div style={{ marginTop:20 }}>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:10 }}>
              <span style={{ fontFamily:'Bebas Neue', fontSize:16, color:'#fff', letterSpacing:0.5 }}>Alertes système</span>
              <span style={{ background:'rgba(239,68,68,0.15)', color:'#F87171', borderRadius:100, fontSize:11, fontWeight:600, padding:'2px 8px' }}>2</span>
            </div>
            {[
              { text:'Paiement en attente — Segou BTP',   bg:'rgba(239,68,68,0.08)',   border:'rgba(239,68,68,0.2)',   color:'#FCA5A5' },
              { text:'Espace stockage >80% — Mali Infra', bg:'rgba(245,158,11,0.08)',  border:'rgba(245,158,11,0.2)', color:'#FCD34D' },
              { text:'Nouvelle inscription à valider',    bg:'rgba(59,130,246,0.08)',  border:'rgba(59,130,246,0.15)',color:'#93C5FD' },
            ].map((a,i)=>(
              <div key={i} style={{ padding:'9px 12px', borderRadius:8, background:a.bg, border:`1px solid ${a.border}`, marginBottom:6, fontSize:12, color:a.color }}>{a.text}</div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
}

// 2. CHEF DE PROJET — Project overview with Gantt + Budget (Image 2 & 7)
function DashboardChefProjet({ projects, user }) {
  const p = projects.find(x=>x.status==='en_cours') || projects[0];
  const delayed = projects.filter(x=>x.end_date&&new Date(x.end_date)<new Date()&&x.status!=='termine').length;

  return (
    <>
      <Alert text="Retard détecté — Phase Terrassement : 3 jours de dépassement. Action requise." type="warning" />

      <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:14, marginBottom:28 }}>
        <KPI label="Avancement global"  value="67%" color="#F59E0B" trend="+4% cette semaine" />
        <KPI label="Budget consommé"    value="82%" color="#EF4444" sub="120M FCFA restants" alert />
        <KPI label="Jours restants"     value="47"  color="#F59E0B" sub="Livraison 28 Avr 2026" />
        <KPI label="Score QHSE"         value="91%" color="#10B981" sub="2 non-conformités" />
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:20 }}>
        <div style={{ background:'#111827', border:'1px solid rgba(255,255,255,0.07)', borderRadius:14, padding:22 }}>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
            <SectionTitle>Planning — phases actives</SectionTitle>
            <span style={{ background:'rgba(245,158,11,0.15)', color:'#F59E0B', borderRadius:100, fontSize:11, fontWeight:600, padding:'3px 10px' }}>3 en cours</span>
          </div>
          <GanttBar label="Terrassement"     pct={78} color="#EF4444" delayed />
          <GanttBar label="Fondations"       pct={55} color="#3B82F6" />
          <GanttBar label="Structures béton" pct={35} color="#10B981" />
          <GanttBar label="Revêtement"       pct={10} color="#6B7280" />
          <GanttBar label="Signalisation"    pct={5}  color="#6B7280" />
          <div style={{ fontSize:11, color:'#6B7280', marginTop:10 }}>| Aujourd'hui (Sem. 11)</div>
        </div>

        <div style={{ background:'#111827', border:'1px solid rgba(255,255,255,0.07)', borderRadius:14, padding:22 }}>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
            <SectionTitle>Répartition budget</SectionTitle>
            <span style={{ fontSize:12, color:'#F59E0B', fontWeight:600 }}>780M FCFA</span>
          </div>
          <div style={{ display:'flex', alignItems:'center', gap:20, marginBottom:20 }}>
            <div style={{ width:80, height:80, borderRadius:'50%', border:'10px solid #EF4444', display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0, position:'relative' }}>
              <div style={{ textAlign:'center' }}>
                <div style={{ fontSize:16, fontWeight:800, color:'#fff' }}>82%</div>
                <div style={{ fontSize:9, color:'#6B7280' }}>utilisé</div>
              </div>
            </div>
            <div style={{ flex:1 }}>
              {[
                {label:"Main d'œuvre",color:'#EF4444', pct:42},
                {label:'Matériaux',   color:'#3B82F6', pct:28},
                {label:'Matériels',   color:'#10B981', pct:19},
                {label:'Divers',      color:'#F59E0B', pct:11},
              ].map((r,i)=>(
                <div key={i} style={{ display:'flex', alignItems:'center', gap:8, marginBottom:8 }}>
                  <div style={{ width:10, height:10, borderRadius:'50%', background:r.color, flexShrink:0 }} />
