export default function DashboardPage() {
  const { user }                          = useAuth();
  const { role, roleColor, roleIcon }     = usePermissions();
  const [projects, setProjects]           = useState([]);
  const [contracts, setContracts]         = useState([]);
  const [loading, setLoading]             = useState(true);

  useEffect(() => {
    Promise.all([
      projectsAPI.list().catch(()=>({data:[]})),
      contractsAPI.list().catch(()=>({data:[]})),
    ]).then(([p,c]) => {
      setProjects(p.data);
      setContracts(c.data);
    }).finally(() => setLoading(false));
  }, []);

  const PAGE_TITLES = {
    super_admin:   'Administration — Vue d\'ensemble',
    chef_projet:   `Vue d'ensemble — ${projects[0]?.name || 'Mes projets'}`,
    maitre_oeuvre: 'Documents & Conformité technique',
    conducteur:    `Journal de Chantier — ${new Date().toLocaleDateString('fr-FR',{day:'2-digit',month:'long',year:'numeric'})}`,
    chef_chantier: 'Mon chantier du jour',
    qhse:          'Contrôle Qualité & Sécurité (QHSE)',
    financier:     `Budget & Achats — ${projects[0]?.name || 'Mes projets'}`,
    magasinier:    'Gestion Stocks & Livraisons',
    sous_traitant: 'Mes tâches & Mon équipe',
    client:        `Suivi — ${projects[0]?.name || 'Mon projet'}`,
  };

  const ACTION_BTNS = {
    super_admin:   { label:'+ Journal du jour', to:'/projects', color:'#9CA3AF' },
    chef_projet:   { label:'Générer rapport IA', to:'/reports',  color:'#F59E0B', primary:true },
    conducteur:    { label:'+ Nouvelle entrée',  to:'/projects', color:'#F59E0B', primary:true },
    chef_chantier: { label:'+ Pointer heures',   to:'/projects', color:'#F59E0B', primary:true },
    qhse:          { label:'Générer rapport QHSE',to:'/qhse',   color:'#F59E0B', primary:true },
    financier:     { label:'Exporter rapport',   to:'/budget',   color:'#F59E0B', primary:true },
    sous_traitant: { label:'Upload photos',       to:'/projects', color:'#C084FC', primary:true },
  };

  const btn = ACTION_BTNS[role];

  return (
    <AppLayout>
      <div style={{ padding:'32px 36px' }} className="animate-fade-in">

        {/* ── Header ── */}
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:28 }}>
          <div>
            <p style={{ color:'#6B7280', fontSize:12, margin:'0 0 4px', fontFamily:'Barlow Condensed', letterSpacing:0.5, textTransform:'uppercase' }}>
              {new Date().toLocaleDateString('fr-FR',{weekday:'long',year:'numeric',month:'long',day:'numeric'})}
            </p>
            <h1 style={{ fontFamily:'Bebas Neue', fontSize:26, color:'#fff', letterSpacing:1, margin:'0 0 6px' }}>
              {PAGE_TITLES[role] || 'Tableau de bord'}
            </h1>
            <div style={{ display:'flex', alignItems:'center', gap:10 }}>
              <RoleBadge role={role} size="sm" />
              <span style={{ fontSize:12, color:'#6B7280' }}>{user?.full_name} · {user?.company_name}</span>
            </div>
          </div>
          <div style={{ display:'flex', gap:10, alignItems:'center', flexShrink:0 }}>
            <Link to="/projects" style={{ padding:'9px 18px', borderRadius:8, border:'1px solid rgba(255,255,255,0.1)', background:'transparent', color:'#9CA3AF', fontSize:13, fontWeight:600, textDecoration:'none', fontFamily:'Barlow Condensed', letterSpacing:0.3 }}>
              + Journal du jour
            </Link>
            {btn && (
              <Link to={btn.to} style={{ padding:'9px 20px', borderRadius:8, background:btn.primary?btn.color:'transparent', border:`1px solid ${btn.color}`, color:btn.primary?'#0D0D1A':btn.color, fontSize:13, fontWeight:700, textDecoration:'none', fontFamily:'Barlow Condensed', letterSpacing:0.3 }}>
                {btn.label}
              </Link>
            )}
          </div>
        </div>

        {/* ── Loading ── */}
        {loading ? (
          <div style={{ textAlign:'center', padding:'80px 0' }}>
            <div style={{ width:36, height:36, border:'3px solid #F59E0B', borderTopColor:'transparent', borderRadius:'50%', animation:'spin 1s linear infinite', margin:'0 auto 14px' }} />
            <p style={{ color:'#6B7280' }}>Chargement...</p>
          </div>
        ) : (
          <>
            {role === 'super_admin'   && <DashboardSuperAdmin   projects={projects} contracts={contracts} user={user} />}
            {role === 'chef_projet'   && <DashboardChefProjet   projects={projects} user={user} />}
            {role === 'maitre_oeuvre' && <DashboardMaitreOeuvre projects={projects} user={user} />}
            {role === 'conducteur'    && <DashboardConducteur   projects={projects} user={user} />}
            {role === 'chef_chantier' && <DashboardChefChantier projects={projects} user={user} />}
            {role === 'qhse'          && <DashboardQHSE         projects={projects} user={user} />}
            {role === 'financier'     && <DashboardFinancier    projects={projects} user={user} />}
            {role === 'magasinier'    && <DashboardMagasinier   projects={projects} user={user} />}
            {role === 'sous_traitant' && <DashboardSousTraitant projects={projects} user={user} />}
            {role === 'client'        && <DashboardClient       projects={projects} user={user} />}
          </>
        )}

      </div>
    </AppLayout>
  );
}
